package com.rohit.inventory.service;
import com.rohit.inventory.dto.request.*; import com.rohit.inventory.dto.response.*; import com.rohit.inventory.entity.*; import com.rohit.inventory.exception.*; import com.rohit.inventory.repository.*; import java.math.BigDecimal; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class InventoryService { private final InventoryRepository inventory; private final InventoryTransactionRepository transactions; private final WarehouseRepository warehouses; private final WarehouseZoneRepository zones; private final ProductRepository products; private final UserRepository users; private final AuditService audit; public InventoryService(InventoryRepository inventory,InventoryTransactionRepository transactions,WarehouseRepository warehouses,WarehouseZoneRepository zones,ProductRepository products,UserRepository users,AuditService audit){this.inventory=inventory;this.transactions=transactions;this.warehouses=warehouses;this.zones=zones;this.products=products;this.users=users;this.audit=audit;}
 @Transactional public InventoryResponse stockIn(StockMovementRequest r,String email){return move(r,email,InventoryTransactionType.STOCK_IN,false,false);} @Transactional public InventoryResponse stockOut(StockMovementRequest r,String email){return move(r,email,InventoryTransactionType.STOCK_OUT,true,false);} @Transactional public InventoryResponse reserve(StockMovementRequest r,String email){return move(r,email,InventoryTransactionType.TRANSFER_RESERVE,true,true);} @Transactional public InventoryResponse release(StockMovementRequest r,String email){return move(r,email,InventoryTransactionType.TRANSFER_RELEASE,false,true);} @Transactional public InventoryResponse adjust(StockAdjustmentRequest r,String email){StockMovementRequest move=new StockMovementRequest(r.warehouseId(),r.zoneId(),r.productId(),r.quantity(),r.reason(),r.referenceType(),r.referenceId());return move(move,email,r.increase()?InventoryTransactionType.ADJUSTMENT_IN:InventoryTransactionType.ADJUSTMENT_OUT,!r.increase(),false);}
 private InventoryResponse move(StockMovementRequest r,String email,InventoryTransactionType type,boolean subtract,boolean reservation){User actor=users.findByEmail(email).orElseThrow(()->new ResourceNotFoundException("User not found"));Warehouse wh=warehouses.findById(r.warehouseId()).orElseThrow(()->new ResourceNotFoundException("Warehouse not found"));Product product=products.findById(r.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found"));WarehouseZone zone=zones.findById(r.zoneId()).orElseThrow(()->new ResourceNotFoundException("Warehouse zone not found"));if(zone.getWarehouse().getId().equals(wh.getId())==false)throw new IllegalArgumentException("Zone does not belong to warehouse");if(wh.getStatus()!=WarehouseStatus.ACTIVE)throw new IllegalArgumentException("Warehouse is not active");if(product.getStatus()!=ProductStatus.ACTIVE)throw new IllegalArgumentException("Product is not active");scope(actor,wh);Inventory inv=inventory.lockByLocation(wh.getId(),zone.getId(),product.getId()).orElseGet(()->newInventory(wh,zone,product));BigDecimal before=inv.getOnHandQuantity(),reservedBefore=inv.getReservedQuantity();if(reservation){if(type==InventoryTransactionType.TRANSFER_RESERVE){if(inv.getAvailableQuantity().compareTo(r.quantity())<0)throw new InsufficientStockException("Insufficient available stock");inv.setReservedQuantity(reservedBefore.add(r.quantity()));}else{if(reservedBefore.compareTo(r.quantity())<0)throw new InsufficientStockException("Cannot release more than reserved stock");inv.setReservedQuantity(reservedBefore.subtract(r.quantity()));}}else if(subtract){if(inv.getAvailableQuantity().compareTo(r.quantity())<0)throw new InsufficientStockException("Insufficient available stock");inv.setOnHandQuantity(before.subtract(r.quantity()));}else inv.setOnHandQuantity(before.add(r.quantity()));inventory.save(inv);transaction(inv,type,reservation?BigDecimal.ZERO:(subtract?r.quantity().negate():r.quantity()),before,reservedBefore,r,actor);audit.record(actor.getId(),type.name(),"INVENTORY",inv.getId(),Map.of("warehouseId",wh.getId(),"productId",product.getId(),"quantity",r.quantity(),"reason",r.reason()));return out(inv);}
 private Inventory newInventory(Warehouse w,WarehouseZone z,Product p){Inventory i=new Inventory();i.setWarehouse(w);i.setZone(z);i.setProduct(p);return i;} private void transaction(Inventory i,InventoryTransactionType type,BigDecimal delta,BigDecimal before,BigDecimal reservedBefore,StockMovementRequest r,User actor){InventoryTransaction tx=new InventoryTransaction();tx.setWarehouse(i.getWarehouse());tx.setZone(i.getZone());tx.setProduct(i.getProduct());tx.setTransactionType(type);tx.setQuantityDelta(delta);tx.setPreviousOnHandQuantity(before);tx.setResultingOnHandQuantity(i.getOnHandQuantity());tx.setPreviousReservedQuantity(reservedBefore);tx.setResultingReservedQuantity(i.getReservedQuantity());tx.setReferenceType(r.referenceType());tx.setReferenceId(r.referenceId());tx.setReason(r.reason());tx.setPerformedBy(actor);transactions.save(tx);} private void scope(User actor,Warehouse warehouse){boolean elevated=actor.getRoles().stream().anyMatch(r->r.getCode().equals("ADMIN")||r.getCode().equals("INVENTORY_MANAGER"));if(!elevated&&actor.getAssignedWarehouses().stream().noneMatch(w->w.getId().equals(warehouse.getId())))throw new org.springframework.security.access.AccessDeniedException("Warehouse is not assigned to this user");} @Transactional(readOnly=true) public Page<InventoryResponse> list(Pageable p){return inventory.findAll(p).map(this::out);} @Transactional(readOnly=true) public InventoryResponse get(UUID id){return out(inventory.findById(id).orElseThrow(()->new ResourceNotFoundException("Inventory not found")));} @Transactional(readOnly=true) public Page<InventoryTransactionResponse> history(UUID warehouseId,UUID zoneId,UUID productId,Pageable p){return transactions.findByWarehouseIdAndZoneIdAndProductId(warehouseId,zoneId,productId,p).map(t->new InventoryTransactionResponse(t.getId(),t.getTransactionType().name(),t.getQuantityDelta(),t.getPreviousOnHandQuantity(),t.getResultingOnHandQuantity(),t.getPreviousReservedQuantity(),t.getResultingReservedQuantity(),t.getReason(),t.getOccurredAt()));} private InventoryResponse out(Inventory i){BigDecimal a=i.getAvailableQuantity();String status=a.signum()==0?"OUT_OF_STOCK":a.compareTo(i.getProduct().getReorderLevel())<=0?"LOW_STOCK":i.getProduct().getMaximumStock().signum()>0&&a.compareTo(i.getProduct().getMaximumStock())>0?"OVERSTOCK":"NORMAL";return new InventoryResponse(i.getId(),i.getWarehouse().getId(),i.getWarehouse().getCode(),i.getZone().getId(),i.getZone().getCode(),i.getProduct().getId(),i.getProduct().getSku(),i.getProduct().getName(),i.getOnHandQuantity(),i.getReservedQuantity(),i.getDamagedQuantity(),a,status,i.getUpdatedAt());}}
